    ("animals", sys.argv[1], 241),
    ("fungi", sys.argv[2], 255),
]
NUMBERED = re.compile(r"^\s*(\d+)\s+(\d+)\s+([0-9]+(?:\.[0-9]*)?(?:[eE][+-]?\d+)?)\s*$")

def alignment_shape(path):
    sequences = []
    current = None
    with path.open(encoding="utf-8") as handle:
        for raw in handle:
            line = raw.strip()
            if not line:
